### 项目进度管理系统

This is a simple progress management system for managing a list of projects. It allows you to add, update, and remove projects.

1. **HTML Structure:**

```html
<!DOCTYPE html>
<html>
<head>
  <title>项目进度管理系统</title>
  <style>
    .project-item {
      margin-bottom: 10px;
      padding: 10px;
      border: 1px solid #ccc;
      display: inline-block;
    }
    .progress-container {
      width: 100%;
      height: 20px;
      background-color: #f3f3f3;
      border-radius: 5px;
      display: flex;
      justify-content: space-between;
    }
    .progress-bar {
      width: 0%;
      height: 100%;
      background-color: #4caf50;
      transition: width 0.5s;
    }
  </style>
</head>
<body>
  <h1>项目列表</h1>
  <div id="projectList"></div>
  <button onclick="addNewProject()">添加新项目</button>
  <button onclick="removeProject('project1')">删除项目1</button>
  <button onclick="removeProject('project2')">删除项目2</button>
  <button onclick="removeProject('project3')">删除项目3</button>
  <button onclick="updateProjects()">更新所有项目进度</button>
</body>
<script>
  // 初始化所有项目进度
  initializeProjects();

  // 显示项目列表
  function displayProjects() {
    const projectList = document.getElementById('projectList');
    const projectItems = '';
    projects.forEach(project => {
      const projectItem = document.createElement('div');
      projectItem.className = 'project-item';
      projectItem.innerHTML = `
        <h3>${project.name}</h3>
        <div class="progress-container">
          <div class="progress-bar" style="width: ${project.querySelector('.progress-bar').getAttribute('data-progress')}%"></div>
          <div class="progress-value">${project.querySelector('.progress-bar').getAttribute('data-progress')}%</div>
        </div>
      `;
      projectItems += `${projectItem.outerHTML}`;
    });
    projectList.innerHTML = `${projectItems}`;
  }

  // 更新所有项目进度
  function updateProjects() {
    projects.forEach(project => {
      const progressBar = project.querySelector('.progress-bar');
      progressBar.setAttribute('data-progress', progressBar.offsetWidth);
      progressBar.style.width = progressBar.offsetWidth + '%';
    });
  }

  // 添加新项目
  function addNewProject() {
    const newProject = {
      id: `project${projects.length + 1}`,
      name: '',
      progress: 0,
      description: '',
      startDate: '',
      endDate: '',
      status: ''
    };
    projects.push(newProject);
    updateProjects();
  }

  // 删除项目
  function removeProject(id) {
    const index = projects.findIndex(project => project.id === id);
    if (index !== -1) {
      projects.splice(index, 1);
      updateProjects();
    }
  }
</script>
